window.RP_SESSION={"id":"S-9be6a23adf1d","messages":[{"id":"RP-III-0114918","time":"2026-06-19T23:43:00+09:00","room":"RP III","name":"마리아 아나이스 에스테르","profile":"Maria Anaïs Ésther","identity":"reviewed","type":"dialogue","body":"-fin","characters":["P-c9505ea97ebc"]},{"id":"RP-III-0114919","time":"2026-06-19T23:43:00+09:00","room":"RP III","name":"마리아 아나이스 에스테르","profile":"Maria Anaïs Ésther","identity":"reviewed","type":"dialogue","body":"... 계속.","characters":["P-c9505ea97ebc"]},{"id":"RP-III-0114920","time":"2026-06-19T23:58:00+09:00","room":"RP III","name":"마리아 아나이스 에스테르","profile":"Maria Anaïs Ésther","identity":"reviewed","type":"dialogue","body":"복동부, 스텔라 씨가 추천해 준 마을로 휴가 온 지도 어언 2주 정도가 지나버렸다.\n\n조용하고 나른한 마을.. 몇 실버로도 풍족한 생황을 누릴 수 있는 완벽한 곳..! 이토록 꿈꾸던 세상에 알맞은 곳이 더 있을까.. 하며 느긋이 지내던 찰나,\n\n도대체 어찌 알았는진 모르겠지만 아랫동네 메어리 씨가 편지는 안 보냈냐고 다짜고짜 재촉을 시작해 버렸다","characters":["P-c9505ea97ebc"]},{"id":"RP-III-0114921","time":"2026-06-20T00:00:00+09:00","room":"RP III","name":"마리아 아나이스 에스테르","profile":"Maria Anaïs Ésther","identity":"reviewed","type":"dialogue","body":"스텔라 씨랑은 마을서 친하게 지내서 그런가, 빡빡하고 잔소리하는 것 하나만큼은 판박이다.\n\n결국 종이 한 장과 잉크, 펜을 꺼내었다.\n\n\"도대체 뭐라 적어야 한담...\"\n\n근래에 글을 좀 썼어야지 도저히 적을 내용이 생각나질 않았다.","characters":["P-c9505ea97ebc"]},{"id":"RP-III-0114922","time":"2026-06-20T00:05:00+09:00","room":"RP III","name":"마리아 아나이스 에스테르","profile":"Maria Anaïs Ésther","identity":"reviewed","type":"dialogue","body":"한 줄만 적었다간 분명 잔소리가 돌아올 테고, 쓸모없는 걸로 부풀려도 결과는 같을 것 같았다.","characters":["P-c9505ea97ebc"]},{"id":"RP-III-0114923","time":"2026-06-20T00:05:00+09:00","room":"RP III","name":"마리아 아나이스 에스테르","profile":"Maria Anaïs Ésther","identity":"reviewed","type":"dialogue","body":"어쩌겠는가... 뭐라도 적어보는 수밖에.","characters":["P-c9505ea97ebc"]},{"id":"RP-III-0114924","time":"2026-06-20T00:05:00+09:00","room":"RP III","name":"마리아 아나이스 에스테르","profile":"Maria Anaïs Ésther","identity":"reviewed","type":"dialogue","body":".\n.\n.","characters":["P-c9505ea97ebc"]},{"id":"RP-III-0114925","time":"2026-06-20T00:32:00+09:00","room":"RP III","name":"마리아 아나이스 에스테르","profile":"Maria Anaïs Ésther","identity":"reviewed","type":"dialogue","body":"스텔라 씨에게,\n\n마리아예요. 무사히 잘 도착해서 쉬고 있답니다. 여기 사람들은 어찌나 친절하고 동네는 또 얼마나 평화로운지 몰라요. 맨날 칙칙하던 그 길드랑은 아주 딴판이라고요! 진심으로 여기 확 눌러앉아 버릴까 고민 중이에요.\n\n편지 쓰는 거 깜빡한 건 미안해요. 메어리 씨한테 뭘 보내신진 모르겠지만 잔소리나 잔뜩 듣고 쓰네요. 저 걱정 안 해도 될 만큼 엄청 잘 먹고 잘 쉬고 있으니까 안심해요.\n길면 2주 정도만 더 쉬다 갈게요. 벌써 이 마을 사람들에게 정이 잔뜩 들어버렸거든요. 매력적인 사람들이라 훌쩍 떠나기 아쉽단 말이죠.\n걱정하시던 상단도 잘 찾았고, 돈을 뺏기거나 어디 길바닥에서 죽지않고 멀쩡히 살아있으니까 저 좀 믿어달라니까요 아시죠?\n\n마리아 아나이스 에스더가","characters":["P-c9505ea97ebc"]},{"id":"RP-III-0114926","time":"2026-06-20T00:32:00+09:00","room":"RP III","name":"마리아 아나이스 에스테르","profile":"Maria Anaïs Ésther","identity":"reviewed","type":"dialogue","body":"-fin","characters":["P-c9505ea97ebc"]},{"id":"RP-III-0114927","time":"2026-06-20T00:32:00+09:00","room":"RP III","name":"마리아 아나이스 에스테르","profile":"Maria Anaïs Ésther","identity":"reviewed","type":"dialogue","body":"... to be continue.","characters":["P-c9505ea97ebc"]},{"id":"RP-III-0115205","time":"2026-06-22T01:42:00+09:00","room":"RP III","name":"마리아 아나이스 에스테르","profile":"Maria Anaïs Ésther","identity":"reviewed","type":"dialogue","body":"https://youtu.be/IVd7CWnrQN0?si=AOtUNPlWFCbq8Omb","characters":["P-c9505ea97ebc"]},{"id":"RP-III-0115206","time":"2026-06-22T01:46:00+09:00","room":"RP III","name":"마리아 아나이스 에스테르","profile":"Maria Anaïs Ésther","identity":"reviewed","type":"dialogue","body":"시원하고 선선한 바람, 왠지 모르게 유난히 시원한 여름밤공기 느끼려 작은 오두막의 창문을 활짝 열었습니다.\n\n한창 이 짧은 시간을 만끽하던 찰나 이런 생각이 스쳐 지나갔습니다.\n\n'이 순간순간이 좋아졌으니, 곧 돌아가야 한다는 게 아닐까' 하고","characters":["P-c9505ea97ebc"]},{"id":"RP-III-0115207","time":"2026-06-22T01:48:00+09:00","room":"RP III","name":"마리아 아나이스 에스테르","profile":"Maria Anaïs Ésther","identity":"reviewed","type":"dialogue","body":"나름의 약속이라면 약속. 분명 돌아가기로 했지만 왜 쉬면 쉴수록 나아지면 나아질수록 다시 돌아가기는 싫어지는 걸까요?\n\n미스터리합니다 당사자인 본인 조차도 이유를 모르겠거든요","characters":["P-c9505ea97ebc"]},{"id":"RP-III-0115208","time":"2026-06-22T01:50:00+09:00","room":"RP III","name":"마리아 아나이스 에스테르","profile":"Maria Anaïs Ésther","identity":"reviewed","type":"dialogue","body":"오늘 아침엔 길가에 핀 이름 모를 들꽃을 한참 바라봤습니다. 바람이 불어 풀냄새가 났고, 저녁 시간엔 몇몇 오두막의 굴뚝에서 연기가 피어올랐습니다. 정말 작고 별거 아닌 모든 게 다 즐겁고 소중해져서일까요? 어쩌면요","characters":["P-c9505ea97ebc"]},{"id":"RP-III-0115209","time":"2026-06-22T01:56:00+09:00","room":"RP III","name":"마리아 아나이스 에스테르","profile":"Maria Anaïs Ésther","identity":"reviewed","type":"dialogue","body":"이게 꿈꾸던 삶이 아니었을까 하는 상상을 합니다.\n\n언젠가 다시 그 치열하다면 치열한 길드로 돌아가야 한다는 걸 알아요.\n나 자신에게도 조금 부끄럽지만 아침엔 빗자루로 마당을 쓸고, 이웃이 건넨 덜 익은 사과를 한 입 먹어보고, 밤에 차가운 우물에서 물을 길어오는 이 별것도 아닌 사소한 일들이 너무 좋아졌습니다.\n\n돌아간다고 뭐, 못할 것도 없는 일들입니다.\n\n오히려 좋다고 생각합니다. 이제 돌아가도 그렇게 축 늘어져 있지만은 않을 것 같아서요.","characters":["P-c9505ea97ebc"]},{"id":"RP-III-0115210","time":"2026-06-22T01:59:00+09:00","room":"RP III","name":"마리아 아나이스 에스테르","profile":"Maria Anaïs Ésther","identity":"reviewed","type":"dialogue","body":"정을 너무 붙이는 습관도 이제 보니 그다지 좋은 행동은 아닌 것 같았습니다. 떠나긴 어려워지거든요.\n\n어차피 2주 정도 더 생각할 시간은 생겼으니 지금은 천천히 만끽하기로 합니다","characters":["P-c9505ea97ebc"]},{"id":"RP-III-0115211","time":"2026-06-22T02:14:00+09:00","room":"RP III","name":"마리아 아나이스 에스테르","profile":"Maria Anaïs Ésther","identity":"reviewed","type":"dialogue","body":"사진","characters":["P-c9505ea97ebc"]},{"id":"RP-III-0115212","time":"2026-06-22T02:14:00+09:00","room":"RP III","name":"마리아 아나이스 에스테르","profile":"Maria Anaïs Ésther","identity":"reviewed","type":"dialogue","body":"적당히 적적히 쉬다가 돌아가야겠습니다","characters":["P-c9505ea97ebc"]},{"id":"RP-III-0115213","time":"2026-06-22T02:14:00+09:00","room":"RP III","name":"마리아 아나이스 에스테르","profile":"Maria Anaïs Ésther","identity":"reviewed","type":"dialogue","body":"ㅇ아마?","characters":["P-c9505ea97ebc"]},{"id":"RP-III-0115214","time":"2026-06-22T02:14:00+09:00","room":"RP III","name":"마리아 아나이스 에스테르","profile":"Maria Anaïs Ésther","identity":"reviewed","type":"dialogue","body":"-fin","characters":["P-c9505ea97ebc"]},{"id":"RP-III-0115215","time":"2026-06-22T02:14:00+09:00","room":"RP III","name":"판정·진행 봇","profile":"《운명의 굴레》","identity":"bot","type":"bot","body":"\"아주 멋진 한판이었어!\"","characters":[]},{"id":"RP-III-0116874","time":"2026-07-01T16:52:00+09:00","room":"RP III","name":"마리아 아나이스 에스테르","profile":"Maria Anaïs Ésther","identity":"reviewed","type":"dialogue","body":"자박자박.. 가져온 가방에 도로 짐을 차곡차곡 쌓아 넣습니다.\n\n너무너무너무너무너무 가기 귀찮지만.. 일주일 휴가를 한 달 동안 다녀와버렸는걸요. 미안해서 어째요.\n\n마지막 식사를 마치고 간단한 집 청소 후 산들바람맞으며 곧 올 상단의 마차를 그저 기다립니다.","characters":["P-c9505ea97ebc"]},{"id":"RP-III-0116875","time":"2026-07-01T16:52:00+09:00","room":"RP III","name":"마리아 아나이스 에스테르","profile":"Maria Anaïs Ésther","identity":"reviewed","type":"dialogue","body":"사진","characters":["P-c9505ea97ebc"]},{"id":"RP-III-0116876","time":"2026-07-01T16:52:00+09:00","room":"RP III","name":"마리아 아나이스 에스테르","profile":"Maria Anaïs Ésther","identity":"reviewed","type":"dialogue","body":"-fin","characters":["P-c9505ea97ebc"]}]};
